def tiao_hou_yongshen(ri_gan, yue_zhi):
    """查日干在月支的调候用神（返回主用神列表，按优先级）。
    例：tiao_hou_yongshen('甲', '寅') -> ['丙', '癸']
    """
    return TIAO_HOU.get(ri_gan, {}).get(yue_zhi, [])

